	"math"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript executes a user-provided Lua script to calculate the final price
// of a product based on the given context.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state with security restrictions
	L := lua.NewState(lua.Options{
		// Disable loading potentially dangerous modules
		SkipOpenLibs: true,
	})
	defer L.Close()

	// Only open safe libraries (math, string, table)
	for _, pair := range []struct {
		lib string
		fn  lua.LGFunction
	}{
		{lua.LoadLibName, lua.OpenPackage}, // Required for module system
	} {
		if err := L.CallByParam(lua.P{
			Fn:      L.NewFunction(pair.fn),
			NRet:    0,
			Protect: true,
		}, lua.LString(pair.lib)); err != nil {
			return 0, fmt.Errorf("failed to load library %s: %w", pair.lib, err)
		}
	}

	// Set up a restricted environment
	baseEnv := L.NewTable()
	L.SetField(baseEnv, "math", L.NewTable())
	L.SetField(baseEnv, "string", L.NewTable())
	L.SetField(baseEnv, "table", L.NewTable())

	// Only expose safe math functions
	mathTable := L.GetField(baseEnv, "math").(*lua.LTable)
	safeMathFuncs := map[string]lua.LGFunction{
		"abs":   func(L *lua.LState) int { L.Push(lua.LNumber(math.Abs(float64(L.CheckNumber(1))))); return 1 },
		"floor": func(L *lua.LState) int { L.Push(lua.LNumber(math.Floor(float64(L.CheckNumber(1))))); return 1 },
		"ceil":  func(L *lua.LState) int { L.Push(lua.LNumber(math.Ceil(float64(L.CheckNumber(1))))); return 1 },
		"max":   func(L *lua.LState) int { L.Push(lua.LNumber(math.Max(float64(L.CheckNumber(1)), float64(L.CheckNumber(2))))); return 1 },
		"min":   func(L *lua.LState) int { L.Push(lua.LNumber(math.Min(float64(L.CheckNumber(1)), float64(L.CheckNumber(2))))); return 1 },
	}
