// ExecutePricingScript executes a user-provided Lua script to calculate the final price
// of a product based on the given context.
// Security measures:
// - Sets resource limits (execution time, memory)
// - Disables dangerous libraries (os, io, debug)
// - Prevents access to global environment
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state with preloaded safe modules
	L := lua.NewState(lua.Options{
		// Skip loading unsafe modules
		SkipOpenLibs: true,
	})
	defer L.Close()

	// Load only safe standard libraries
	safeLibs := []lua.LGFunction{
		lua.OpenBase,   // Basic functions (math, string, etc.)
		lua.OpenMath,   // Math library
		lua.OpenString, // String manipulation
		lua.OpenTable,  // Table manipulation
	}
	for _, lib := range safeLibs {
		lib(L)
	}

	// Remove dangerous functions from base library
	removeDangerousFunctions(L)

	// Set execution timeout using Go's context with timeout
	type scriptResult struct {
		val float64
		err error
	}
	resultCh := make(chan scriptResult, 1)

	go func() {
		// Load and execute the script in a separate goroutine
		if err := L.DoString(script); err != nil {
			resultCh <- scriptResult{0, fmt.Errorf("failed to execute Lua script: %w", err)}
			return
		}

		// Get the calculate_final_price function from global scope
		fn := L.GetGlobal("calculate_final_price")
		if fn.Type() != lua.LTFunction {
			resultCh <- scriptResult{0, fmt.Errorf("calculate_final_price is not a function or not defined")}
			return
		}

		// Convert Go context map to Lua table
		ctxTable := L.NewTable()
		for k, v := range ctx {
			// Validate key to prevent table manipulation attacks
			if len(k) > 64 {
				resultCh <- scriptResult{0, fmt.Errorf("context key too long: %s", k)}
				return
			}
			L.SetField(ctxTable, k, lua.LNumber(v))
		}

		// Call the function with the context table
		if err := L.CallByParam(lua.P{
			Fn:      fn,
			NRet:    1,
			Protect: true,
		}, ctxTable); err != nil {
			resultCh <- scriptResult{0, fmt.Errorf("failed to call calculate_final_price: %w", err)}
			return
		}

		// Get the result from the Lua stack
		luaResult := L.Get(-1)
		L.Pop(1) // Remove the result from the stack

		// Convert result to float64
		if luaResult.Type() != lua.LTNumber {
			resultCh <- scriptResult{0, fmt.Errorf("calculate_final_price did not return a number")}
			return
		}

		resultCh <- scriptResult{float64(luaResult.(lua.LNumber)), nil}
	}()

	// Wait for result with timeout
	select {
	case res := <-resultCh:
		return res.val, res.err
	case <-time.After(5 * time.Second):
		L.Close() // Force close the Lua state
		return 0, fmt.Errorf("script execution timed out")
	}
