// removeDangerousFunctions removes functions that could be used for attacks
func removeDangerousFunctions(L *lua.LState) {
	// Remove functions that allow file system access
	dangerousFuncs := []string{
		"dofile", "loadfile", "require", "module",
		"collectgarbage", "newproxy",
	}
	for _, name := range dangerousFuncs {
		L.SetGlobal(name, lua.LNil)
	}

	// Override print to prevent output
	L.SetGlobal("print", lua.LNil)

	// Remove debug library access
	L.SetGlobal("debug", lua.LNil)
	L.SetGlobal("io", lua.LNil)
	L.SetGlobal("os", lua.LNil)
	L.SetGlobal("package", lua.LNil)
	L.SetGlobal("coroutine", lua.LNil)
