// sanitizeKey ensures the key doesn't contain dangerous characters
func sanitizeKey(key string) string {
	// Only allow alphanumeric characters and underscores
	safe := make([]byte, 0, len(key))
	for i := 0; i < len(key); i++ {
		c := key[i]
