// ExecutePricingScript executes a Lua pricing script and returns the final price.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	L := lua.NewState()
	defer L.Close()

	// Load the script
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to load script: %w", err)
	}

	// Get the calculate_final_price function
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, errors.New("calculate_final_price function not found or not a function")
	}

	// Convert context map to Lua table
	ctxTable := L.NewTable()
	for key, value := range ctx {
		L.SetField(ctxTable, key, lua.LNumber(value))
	}

	// Call the function
	err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable)

	if err != nil {
		return 0, fmt.Errorf("failed to execute calculate_final_price: %w", err)
	}

	// Get the return value
	ret := L.Get(-1)
	L.Pop(1)

	// Check if the return value is a number
	if ret.Type() != lua.LTNumber {
		return 0, errors.New("calculate_final_price must return a number")
	}

	// Convert to float64
	price := float64(ret.(lua.LNumber))
	return price, nil
}

