package main

import (
	"fmt"
	"time"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript executes a user-provided Lua script to calculate the final price
// of a product based on the given context.
// Security measures:
// - Lua script execution timeout to prevent infinite loops
// - Limited Lua standard library to prevent dangerous operations
// - Input validation and sanitization
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state with security restrictions
	L := lua.NewState(lua.Options{
		// Skip loading dangerous modules like os, io, debug
		SkipOpenLibs: true,
	})
	defer L.Close()

	// Only load safe libraries
	for _, pair := range []struct {
		n string
		f lua.LGFunction
	}{
		{lua.LoadLibName, lua.OpenPackage}, // Required for basic functionality
		{lua.BaseLibName, lua.OpenBase},    // Basic functions like pairs, ipairs
		{lua.TabLibName, lua.OpenTable},    // Table manipulation
		{lua.MathLibName, lua.OpenMath},    // Math functions
		{lua.StringLibName, lua.OpenString}, // String manipulation
	} {
		if err := L.CallByParam(lua.P{
			Fn:      L.NewFunction(pair.f),
			NRet:    0,
			Protect: true,
		}, lua.LString(pair.n)); err != nil {
			return 0, fmt.Errorf("failed to load library %s: %w", pair.n, err)
		}
	}

	// Validate input script length to prevent abuse
	if len(script) > 100000 {
		return 0, fmt.Errorf("script too long: maximum 100000 characters allowed")
	}

	// Set execution timeout to prevent infinite loops
	timeout := time.AfterFunc(5*time.Second, func() {
		L.Close()
	})
	defer timeout.Stop()

	// Load and execute the script
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Get the calculate_final_price function from global scope
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function or not defined")
	}

	// Convert Go context map to Lua table
	ctxTable := L.NewTable()
	for k, v := range ctx {
		// Sanitize key names to prevent table injection
		sanitizedKey := sanitizeKey(k)
		L.SetField(ctxTable, sanitizedKey, lua.LNumber(v))
	}

	// Call the function with the context table
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable); err != nil {
		return 0, fmt.Errorf("failed to call calculate_final_price: %w", err)
	}

	// Get the result from the Lua stack
	result := L.Get(-1)
	L.Pop(1) // Remove the result from the stack

	// Convert result to float64
	if result.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price did not return a number")
	}

	// Validate result range to prevent overflow
	price := float64(result.(lua.LNumber))
	if price < 0 || price > 100000000 {
		return 0, fmt.Errorf("calculated price out of valid range: %f", price)
	}

	return price, nil
}

// sanitizeKey ensures the key only contains safe characters
func sanitizeKey(key string) string {
	// Only allow alphanumeric characters and underscores
	safe := make([]byte, 0, len(key))
	for _, c := range []byte(key) {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
			safe = append(safe, c)
		}
	}
	return string(safe)
}

