// disableDangerousGlobals removes dangerous functions and modules from the Lua environment
func disableDangerousGlobals(L *lua.LState) {
	// Remove dangerous global functions
	dangerousGlobals := []string{
		"dofile", "loadfile", "require", "module",
		"rawget", "rawset", "rawequal",
		"setfenv", "getfenv",
		"newproxy",
		"collectgarbage",
		"error", "pcall", "xpcall",
	}
	for _, name := range dangerousGlobals {
		L.SetGlobal(name, lua.LNil)
	}

	// Remove dangerous modules
	dangerousModules := []string{
		"io", "os", "debug", "package",
	}
	for _, name := range dangerousModules {
		L.SetGlobal(name, lua.LNil)
	}

	// Restrict the string library
	restrictStringLibrary(L)
}

// restrictStringLibrary restricts dangerous string operations
func restrictStringLibrary(L *lua.LState) {
	// Get the string table
	stringTable := L.GetGlobal("string")
	if stringTable.Type() == lua.LTTable {
		// Remove dangerous string functions
		dangerousStringFuncs := []string{
			"dump", "gsub", "rep", "reverse",
		}
